import java.util.Scanner;
class Rectangle {
    int width;
    int height;
    Rectangle(int width, int height) {
        this.width = width;
        this.height = height;
    }
    int area() {
        return width * height;
    }
}
public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Rectangle r = new Rectangle(sc.nextInt(), sc.nextInt());
        System.out.println(r.area());
    }
}

import java.util.Scanner;
class Account {
    private int balance;
    Account(int balance) {
        this.balance = balance;
    }
    void deposit(int amount) {
        balance += amount;
    }
    void withdraw(int amount) {
        if (amount <= balance) {
            balance -= amount;
        }
    }
    int getBalance() {
        return balance;
    }
}
public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Account acct = new Account(sc.nextInt());
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            String op = sc.next();
            int amount = sc.nextInt();
            if (op.equals("D")) {
                acct.deposit(amount);
            } else {
                acct.withdraw(amount);
            }
        }
        System.out.println(acct.getBalance());
    }
}
